class Dinic {
    struct Edge {
        int to;
        int reverseIndex;
        int capacity;
    };

    vector<vector<Edge>> graph;
    vector<int> level;
    vector<int> nextEdge;

public:
    explicit Dinic(int size) : graph(size), level(size), nextEdge(size) {}

    void addEdge(int from, int to, int capacity) {
        Edge forward{to, static_cast<int>(graph[to].size()), capacity};
        Edge reverse{from, static_cast<int>(graph[from].size()), 0};
        graph[from].push_back(forward);
        graph[to].push_back(reverse);
    }

    bool buildLevelGraph(int source, int sink) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[source] = 0;
        q.push(source);

        while (!q.empty()) {
            int vertex = q.front();
            q.pop();

            for (const Edge& edge : graph[vertex]) {
                if (edge.capacity > 0 && level[edge.to] == -1) {
                    level[edge.to] = level[vertex] + 1;
                    q.push(edge.to);
                }
            }
        }

        return level[sink] != -1;
    }

    int sendFlow(int vertex, int sink, int flow) {
        if (vertex == sink) return flow;

        for (int& i = nextEdge[vertex]; i < static_cast<int>(graph[vertex].size()); ++i) {
            Edge& edge = graph[vertex][i];

            if (edge.capacity <= 0 || level[edge.to] != level[vertex] + 1)
                continue;

            int sent = sendFlow(edge.to, sink, min(flow, edge.capacity));
            if (sent == 0) continue;

            edge.capacity -= sent;
            graph[edge.to][edge.reverseIndex].capacity += sent;
            return sent;
        }

        return 0;
    }

    int maximumFlow(int source, int sink) {
        int result = 0;
        const int infinity = numeric_limits<int>::max();

        while (buildLevelGraph(source, sink)) {
            fill(nextEdge.begin(), nextEdge.end(), 0);

            while (int sent = sendFlow(source, sink, infinity))
                result += sent;
        }

        return result;
    }
};

