        Edge forward{to, capacity, static_cast<int>(graph[to].size())};
        Edge backward{from, 0, static_cast<int>(graph[from].size())};
        graph[from].push_back(forward);
        graph[to].push_back(backward);
    }

    int maximumFlow(int source, int sink) {
        int flow = 0;

        while (bfs(source, sink)) {
            fill(iter.begin(), iter.end(), 0);
            while (int pushed = dfs(source, sink, numeric_limits<int>::max())) {
                flow += pushed;
            }
        }

        return flow;
    }

private:
    vector<vector<Edge>> graph;
    vector<int> level;
    vector<int> iter;

    bool bfs(int source, int sink) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[source] = 0;
        q.push(source);

        while (!q.empty()) {
            int vertex = q.front();
            q.pop();

            for (const Edge& edge : graph[vertex]) {
                if (edge.capacity > 0 && level[edge.to] == -1) {
                    level[edge.to] = level[vertex] + 1;
                    q.push(edge.to);
                }
            }
        }

        return level[sink] != -1;
    }

    int dfs(int vertex, int sink, int pushed) {
        if (vertex == sink) {
            return pushed;
        }

        for (int& i = iter[vertex]; i < static_cast<int>(graph[vertex].size()); ++i) {
            Edge& edge = graph[vertex][i];

            if (edge.capacity == 0 || level[edge.to] != level[vertex] + 1) {
                continue;
            }

            int flow = dfs(edge.to, sink, min(pushed, edge.capacity));
            if (flow == 0) {
                continue;
            }

            edge.capacity -= flow;
            graph[edge.to][edge.reverse].capacity += flow;
            return flow;
        }

        return 0;
    }
};

